template:
// CONTROLLED SAMPLE SELECTION | BPM: 100
setcps(100/240)
stack(
  /* @layer KICK */
  s("{{kick}}*4").gain(0.45).pan(0.5).room(0).delay(0).clip(0.9),
  /* @layer SNARE */
  s("{{snare}} [~ {{snare}}] {{snare}} [{{snare}} ~]").gain(0.45).pan(0.5).room(0).delay(0).clip(0.9),
  /* @layer HAT */
  s("{{hat}}*8").gain(0.45).pan(0.5).room(0).delay(0).clip(0.9)
)

// CONTROLLED SAMPLE SELECTION | BPM: 100
